import React, { useState, useEffect } from "react";
import Navbar from "./Navbar";
import Intro from "./Intro";
import Benefits from "./Benefits";
import Work from "./Work";
import Pricing from "./Pricing";
import Faqs from "./Faqs";
import Footer from "./Footer";
import ServicesTicker from "./ServicesTicker";
import TopNavigation from "./TopNavigation";
import Steps from "./Steps";
import AccountManagementModal from "./AccountManagementModal";
import About from "./About";
import CaseStudies from "./CaseStudies";

export default function Home() {
  const [showModal, setShowModal] = useState(false);
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const scrollTo = params.get("scrollTo");
    if (scrollTo) {
      const el = document.getElementById(scrollTo);
      if (el) {
        el.scrollIntoView({ behavior: "smooth" });
      }
    }
  }, []);

  useEffect(() => {
    if (showModal) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "auto";
    }

    return () => {
      document.body.style.overflow = "auto";
    };
  }, [showModal]);

  // Add scroll-triggered animations
  useEffect(() => {
    const observerOptions = {
      threshold: 0.5,
      rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const delay = entry.target.dataset.animationDelay || 0;
          setTimeout(() => {
            entry.target.style.opacity = "1";
            entry.target.style.transform = "translateY(0)";
          }, delay * 100);
        }
      });
    }, observerOptions);

    // Observe elements for scroll animations with staggered delays
    const animatedElements = document.querySelectorAll(
      ".hire-to-item, .testimonial-section,.benefits-item, .case-study-card, .work-item, .pricing-option, .faqs-question, .about-content, .bottom-cta-container, .site-feature-col, .plan-feature-col"
    );

    animatedElements.forEach((el, index) => {
      el.style.opacity = "0";
      el.style.transform = "translateY(30px)";
      el.style.transition = "opacity 0.6s ease-out, transform 0.6s ease-out";
      el.dataset.animationDelay = index % 6; // Stagger delays in groups of 6
      observer.observe(el);
    });

    return () => {
      animatedElements.forEach((el) => observer.unobserve(el));
    };
  }, []);

  return (
    <>
      <Navbar
        showModal={showModal}
        setShowModal={setShowModal}
        showEmailForm={showEmailForm}
        setShowEmailForm={setShowEmailForm}
        email={email}
        setEmail={setEmail}
        error={error}
        setError={setError}
        isSubmitting={isSubmitting}
        setIsSubmitting={setIsSubmitting}
        success={success}
        setSuccess={setSuccess}
      />
      <AccountManagementModal
        showModal={showModal}
        setShowModal={setShowModal}
        showEmailForm={showEmailForm}
        setShowEmailForm={setShowEmailForm}
        email={email}
        setEmail={setEmail}
        error={error}
        setError={setError}
        isSubmitting={isSubmitting}
        setIsSubmitting={setIsSubmitting}
        success={success}
        setSuccess={setSuccess}
      />
      <TopNavigation
        showModal={showModal}
        setShowModal={setShowModal}
        showEmailForm={showEmailForm}
        setShowEmailForm={setShowEmailForm}
        email={email}
        setEmail={setEmail}
        error={error}
        setError={setError}
        isSubmitting={isSubmitting}
        setIsSubmitting={setIsSubmitting}
        success={success}
        setSuccess={setSuccess}
      />
      <Intro />
      {/* <ServicesTicker /> */}
      <About />
      <Steps />
      <Benefits />
      <CaseStudies />
      <Pricing />
      <Faqs />
      <Footer />
    </>
  );
}
